const body = $input.first().json.body || $input.first().json;

const name  = (body.customer_name || body.name || '').trim();
const email = (body.customer_email || body.email || '').trim().toLowerCase();
const phone = (body.customer_phone || body.phone || body.contact || '').trim();

if (!name)  throw new Error('customer_name is required');
if (!email && !phone) throw new Error('At least one of customer_email or customer_phone is required');

return [{ json: { name, email, phone } }];

const validated   = $('Validate Input').first().json;
const name        = validated.name;
const email       = validated.email;
const phone       = validated.phone;

const custJson    = $input.first().json;
const customers   = custJson.data || (Array.isArray(custJson) ? custJson : []);

// Strip non-digits for phone comparison
const digitsOnly  = s => (s || '').replace(/\D/g, '');
const phoneDigits = digitsOnly(phone);

const match = customers.find(c =>
  (email && c.email && c.email.toLowerCase() === email) ||
  (phoneDigits.length >= 7 && digitsOnly(c.phone) === phoneDigits)
);

if (match) {
  return [{ json: {
    customer_id:    match.customer_id || match.id,
    customer_name:  match.full_name   || match.name || name,
    customer_email: match.email || email,
    customer_phone: match.phone || phone,
    is_new:         false
  }}];
}

// No match — flag for creation
return [{ json: { customer_id: null, customer_name: name, customer_email: email, customer_phone: phone, is_new: true } }];

// After creation — extract the new customer_id from the DB response
const resp = $input.first().json;
const newId = resp.customer_id || resp.id || resp.data?.customer_id || resp.data?.id || '';
const prev  = $('Find Existing Customer').first().json;
return [{ json: {
  customer_id:    newId,
  customer_name:  prev.customer_name,
  customer_email: prev.customer_email,
  customer_phone: prev.customer_phone,
  is_new:         true
}}];

